function WeeklySetup({data,plans,save,note}){const [open,setOpen]=useState(false),[schedule,setSchedule]=useState(data.schedule||{});return <article><button className="lime wide" onClick={()=>setOpen(!open)}>Set up weekly workouts</button>{open&&<div><p>Choose your training days and one or more workouts per day. Leave a day empty for rest. This schedule repeats every week. Edit each workout below to choose its exercises.</p>{['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'].map(day=><fieldset key={day}><legend>{day}</legend>{plans.filter(p=>p.id!=='daily'&&!p.deleted&&!p.draft).map(p=><label style={{display:'block',padding:8}} key={p.id}><input type="checkbox" checked={(schedule[day]||[]).includes(p.id)} onChange={()=>setSchedule({...schedule,[day]:(schedule[day]||[]).includes(p.id)?schedule[day].filter(id=>id!==p.id):[...(schedule[day]||[]),p.id]})}/> {p.name}</label>)}</fieldset>)}<button className="lime wide" onClick={()=>{save({...data,schedule});note('Weekly schedule saved');setOpen(false)}}>Save weekly schedule</button></div>}</article>}
const exerciseGuides={push:{focus:'Chest',equipment:'Bodyweight',preparation:'Place your hands just wider than shoulder width and stack them below your shoulders. Extend your legs behind you and keep a straight line from head to heels.',execution:['Brace your abdomen and keep your hips level.','Bend your elbows at a comfortable angle and lower your chest toward the floor.','Press through your palms until your arms are straight, without locking your elbows.'],tips:['Keep your neck in line with your spine.','Use a knee push-up variation if you cannot keep a steady body line.']},pullup:{focus:'Back',equipment:'Bodyweight',preparation:'Take a secure overhand grip on the bar, slightly wider than shoulder width. Begin from a controlled hang with your shoulders engaged.',execution:['Brace your core and draw your shoulder blades down.','Pull until your chin clears the bar without swinging or kicking.','Lower yourself slowly to a controlled hang before the next rep.'],tips:['Use a resistance band or assisted machine if needed.','Avoid dropping suddenly from the top position.']}};
const guideFor=e=>exerciseGuides[e.id]||({focus:e.muscle,equipment:e.equipment,preparation:`Set up your ${e.equipment.toLowerCase()} safely. Keep a stable posture and brace your core before starting ${e.name}.`,execution:[`Move through the exercise with a controlled range of motion.`,`Keep your body aligned and avoid using momentum.`,`Breathe out during effort, then return slowly to the start.`],tips:['Use a comfortable load that lets you stay controlled.','Stop if you feel sharp pain or lose stable form.']});
