function ExerciseModal({item,record,close}){let media=exerciseMedia[item.id];return <div className="modal"><div className="exercise-modal"><button className="close" onClick={close}>×</button>{record?<><h2>Workout Record</h2><div className="record-head"><Image src={item.image}/><span><b>{item.name}</b><small>Completed</small></span></div><dl><dt>Date</dt><dd>{new Date(record.finished_at).toLocaleDateString()}</dd><dt>Start time</dt><dd>{new Date(record.started_at).toLocaleTimeString()}</dd><dt>Finish time</dt><dd>{new Date(record.finished_at).toLocaleTimeString()}</dd><dt>Total duration</dt><dd>{Math.floor(record.duration_seconds/60)} min {record.duration_seconds%60} sec</dd><dt>Sets</dt><dd>{record.sets}</dd><dt>Reps</dt><dd>{record.reps}</dd><dt>Weight</dt><dd>{record.weight_kg} kg</dd></dl></>:<><h2>{item.name} demo</h2>{media?<ExerciseVideo exercise={item}/>:<><Image src={item.image}/><p>Licensed exercise video has not yet been added for this movement. RK FITNESS will not play an unrelated placeholder video. Follow the preparation and execution guide while a verified exercise-specific media asset is unavailable.</p></>}</>}<button className="lime wide" onClick={close}>Done</button></div></div>}
