function Profile({data,save,go,note,uploadAvatar}){
  let[u,setU]=useState(data.user),[edit,setEdit]=useState(false),[photoBusy,setPhotoBusy]=useState(false),p=stats(data.workouts),level=levelOf(p.xp);
  useEffect(()=>setU(data.user),[data.user]);
  const update=async()=>{save({...data,user:u});const{error}=await supabase.auth.updateUser({data:{full_name:u.name,username:u.username}});if(error)console.error('RK FITNESS profile metadata update failed',error);setEdit(false);note('Profile updated')};
  const changePhoto=async event=>{let file=event.target.files?.[0];if(!file)return;setPhotoBusy(true);let url=await uploadAvatar(file);setPhotoBusy(false);if(url)setU(current=>({...current,avatarUrl:url}));event.target.value=''};
  return <section><Top title="My Profile" action={<button onClick={()=>setEdit(!edit)}>{edit?'Done':'Edit'}</button>}/><div className="profile"><div className="avatar big">{u.avatarUrl?<img src={u.avatarUrl} alt={`${u.name} profile`}/>:u.name[0]}</div><h2>{u.name}</h2><p>@{u.username||u.name.toLowerCase().replace(/[^a-z0-9]+/g,'_')} · {u.email||'Account email unavailable'}</p><p>Level {level} · {u.goal}</p><aside><b>{p.streak}<small>Day streak</small></b><b>{data.workouts.length}<small>Workouts</small></b><b>{p.xp}<small>XP</small></b></aside></div>{edit?<div className="edit-profile"><label className="avatar-upload">Profile photo<input type="file" accept="image/jpeg,image/png,image/webp" onChange={changePhoto} disabled={photoBusy}/><small>{photoBusy?'Uploading photo…':'JPG, PNG, or WebP · max 5 MB · public image link'}</small></label><Field label="Display name" value={u.name} onChange={name=>setU({...u,name})}/><Field label="Username" value={u.username||''} onChange={username=>setU({...u,username:username.replace(/[^a-zA-Z0-9_]/g,'').slice(0,24)})}/><label className="field">Email address<input value={u.email||''} readOnly/></label><Field label="Weight (kg)" type="number" value={u.weight} onChange={weight=>setU({...u,weight:+weight})}/><Field label="Target weight (kg)" type="number" value={u.target} onChange={target=>setU({...u,target:+target})}/><button className="lime wide" onClick={update}>Save Profile</button></div>:['Achievements','Goals & Plans','Food Tracker','Settings'].map(x=><button className="menu" onClick={()=>go(x==='Achievements'?'achievements':x==='Goals & Plans'?'goals':x==='Food Tracker'?'food':'settings')} key={x}>{x}<b>›</b></button>)}</section>
}function Goals({data,save,go,note}){let[u,setU]=useState(data.user),commit=()=>{save({...data,user:u});note('Goals updated');go('me')};return <section><Top title="Goals & Plans" back={()=>go('me')}/><h3>Fitness goal</h3><Pick options={['Muscle Gain','Keep Fit','Strength','Weight Loss']} value={u.goal} set={goal=>setU({...u,goal})}/><h3>Focus areas</h3><Multi options={['Full Body','Chest','Back','Legs','Arms','Shoulders','Abs']} value={u.focus} set={focus=>setU({...u,focus})}/><button className="lime wide bottom" onClick={commit}>Save Goals</button></section>}
const LEVEL_TITLES=['Dormant','Spark','Initiate','Recruit','Trainee','Disciple','Riser','Vigilant','Forerunner','Awakened','Ember','Ranger','Sentinel','Pioneer','Strider','Vanguard','Harbinger','Wayfinder','Invoker','Ascendant','Crystalbound','Skyborne','Ironwill','Frostveil','Stormcaller','Wildheart','Luminary','Starforged','Dawnbreaker','Exalted','Nightblade','Runeborn','Voidwalker','Flameguard','Moonseeker','Windsworn','Soulforged','Lightbearer','Crownbound','Supreme','Gilded','Highborn','Kingsguard','Sunlance','Goldwarden','Oathkeeper','Lionheart','Thronebound','Royalty','Legend','Bloodfire','Dreadnought','Hellbound','Inferno','Red Reaver','Warbringer','Dragonheart','Ravager','Worldbreaker','Mythic','Nebula','Starweaver','Astral Knight','Gravityborn','Celestial','Darkmatter','Cosmic Blade','Eternal','Galaxy Lord','Apocalypse','Riftwalker','Sky Tyrant','Seraph','Divine Blade','Immortal','Heavenfall','Godslayer','Radiant One','Infinite','Divine Ascendant','Quantum','Dimensional','Prism Lord','Nova King','Aetherborn','Eclipse Lord','Chronomancer','Limitless','Paragon','Transcendent','Omniscient','Zenith Guard','Star Emperor','Eternal King','Final Form','THE APEX'];
const RANKS=[['E','The Awakening','#c9d1d9'],['D','The Rising','#32d583'],['C','The Evolution','#43a7ff'],['B','The Dominance','#be71ff'],['A','The Elite','#ffc34a'],['S','The Awakened','#ff594f'],['SS','The Unstoppable','#a875ff'],['SSS','The Divine','#eef6ff'],['EX','The Transcendence','#43e7ff'],['ZENITH','The Absolute','#ffd84d']];
const levelOf=x=>levelState(x).level;
const rankIndex=level=>Math.min(9,Math.floor((level-1)/10));
function RankEmblem({rank,small=false}){let r=RANKS[rank],id=`rank-${rank}`;return <svg className={'rank-emblem '+(small?'small':'')} viewBox="0 0 100 112" style={{'--rank-color':r[2]}} aria-label={`${r[0]} rank emblem`}><defs><linearGradient id={id} x1="0" x2="1"><stop stopColor="#131820"/><stop offset=".55" stopColor={r[2]}/><stop offset="1" stopColor="#101217"/></linearGradient></defs><path d="M50 4 90 20 84 72 50 106 16 72 10 20Z" fill={`url(#${id})`} stroke={r[2]} strokeWidth="3"/><path d="M50 16 74 29 69 65 50 86 31 65 26 29Z" fill="#0b0e12" stroke={r[2]} strokeOpacity=".75"/><path d="M34 48h32M50 31v38" stroke={r[2]} strokeWidth="4" strokeLinecap="round"/><text x="50" y="61" textAnchor="middle" fill="white" fontSize={r[0].length>2?'18':'28'} fontWeight="800">{r[0]}</text></svg>}
function Achievements({data}){let[view,setView]=useState('achievements'),[filter,setFilter]=useState('All');if(view==='rank')return <RankProgress data={data} back={()=>setView('achievements')}/>;if(view==='progress')return <Progress data={data} back={()=>setView('achievements')}/>;let p=stats(data.workouts),level=levelOf(p.xp),done=data.workouts.length,defs=[['Training','First Workout','Complete your first workout',done,1],['Training','Momentum','Complete 5 workouts',done,5],['Training','Iron Habit','Complete 20 workouts',done,20],['Training','Century','Complete 100 workouts',done,100],['Streak','Seven Days','Reach a 7-day streak',p.streak,7],['Streak','Daily Discipline','Reach a 30-day streak',p.streak,30],['Level','Level 10','Reach level 10',level,10],['Level','Level 25','Reach level 25',level,25],['Level','Level 50','Reach level 50',level,50],['Level','Level 75','Reach level 75',level,75],['Special','The Apex','Reach level 100',level,100]],list=defs.filter(x=>filter==='All'||x[0]===filter),unlocked=defs.filter(x=>x[3]>=x[4]).length,percentage=Math.round(unlocked/defs.length*100);return <section className="rpg"><Top title="Achievements"/><div className="rpg-actions"><button onClick={()=>setView('rank')}>Rank Progression</button><button onClick={()=>setView('progress')}>Progress</button></div><div className="achievement-overview"><div className="completion-ring" style={{'--completion':`${percentage*3.6}deg`}}><b>{percentage}%</b></div><span><b>Achievement Progress</b><small>{unlocked} / {defs.length} unlocked</small></span></div><div className="rpg-filters">{['All','Training','Streak','Level','Special'].map(x=><button className={filter===x?'on':''} onClick={()=>setFilter(x)} key={x}>{x}</button>)}</div><div className="achievement-grid">{list.map(([category,name,description,current,target])=>{let earned=current>=target,percent=Math.min(100,Math.round(current/target*100));return <article className={'rpg-achievement '+(earned?'unlocked':'locked')} key={name}><i className="achievement-token">{earned?'':' '}</i><span><b>{name}</b><small>{description}</small><em>{current} / {target} · {percent}%</em></span><strong>{earned?'Unlocked':'Locked'}</strong></article>})}</div></section>}
function RankProgress({data,back}){let p=stats(data.workouts),level=levelOf(p.xp),[selected,setSelected]=useState(rankIndex(level)),rank=RANKS[selected],range=`${selected*10+1}–${selected===9?100:(selected+1)*10}`,next=RANKS[Math.min(9,selected+1)];return <section className="rpg"><Top title="Rank Progression" back={back}/><div className="rank-hero" style={{'--rank-color':rank[2]}}><RankEmblem rank={selected}/><span><small>CURRENT RANK</small><h1>{rank[0]} RANK</h1><b>{rank[1]}</b><p>Level {level} · Range {range}</p></span></div><div className="rank-levels">{Array.from({length:10},(_,i)=>{let n=selected*10+i+1;return <i className={n<level?'complete':n===level?'current':''} key={n}>{n}</i>})}</div><h3>All Ranks (1–100)</h3><div className="rank-stack">{RANKS.map((r,i)=>{let unlocked=level>=i*10+1;return <button className={i===selected?'selected':''} onClick={()=>setSelected(i)} key={r[0]}><RankEmblem rank={i} small/><span><b>{r[0]} Rank · Lv {i*10+1}–{i===9?100:(i+1)*10}</b><small>{r[1]}</small></span><em>{unlocked?'✓':'Locked'}</em></button>})}</div><div className="next-rank"><small>NEXT RANK</small><b>{selected===9?'THE APEX':`${next[0]} Rank · ${next[1]}`}</b></div></section>}
function Progress({data,back}){let p=stats(data.workouts),state=levelState(p.xp),level=state.level,[tab,setTab]=useState('Level Progress'),rank=rankIndex(level),unlocked=achievementCount(data,p,level);return <section className="rpg"><Top title="Progress" back={back}/><div className="rpg-tabs">{['Level Progress','Overall Stats'].map(x=><button className={tab===x?'on':''} onClick={()=>setTab(x)} key={x}>{x}</button>)}</div>{tab==='Level Progress'?<><div className="progress-hero"><RankEmblem rank={rank}/><span><small>{RANKS[rank][0]} RANK · {LEVEL_TITLES[level-1]}</small><h1>Level {level}</h1><b>{p.xp} XP</b><em><i style={{width:`${state.progress}%`}}/></em><small>{level===100?'THE APEX achieved':`${state.next} XP to level ${level+1}`}</small></span></div><div className="level-grid">{Array.from({length:100},(_,i)=>{let n=i+1;return <button className={n<level?'complete':n===level?'current':n%10===0?'milestone':''} key={n} title={`${n}: ${LEVEL_TITLES[i]}`}>{n}</button>})}</div></>:<div className="overall-stats"><StatBox n={data.workouts.length} t="Lifetime workouts"/><StatBox n={p.minutes>=60?`${Math.floor(p.minutes/60)}h ${p.minutes%60}m`:`${p.minutes}m`} t="Training time"/><StatBox n={p.xp} t="Total XP"/><StatBox n={`Lv ${level}`} t="Current level"/><StatBox n={`${RANKS[rank][0]} Rank`} t="Current rank"/><StatBox n={`${RANKS[rankIndex(Math.max(level,1))][0]} Rank`} t="Highest rank"/><StatBox n={`${p.streak} days`} t="Current streak"/><StatBox n={`${p.longest} days`} t="Longest streak"/><StatBox n={unlocked} t="Achievements unlocked"/><StatBox n={`${p.activeDays} days`} t="Active training days"/></div>}</section>}
const achievementCount=(data,p,level)=>[data.workouts.length>=1,data.workouts.length>=5,data.workouts.length>=20,data.workouts.length>=100,p.streak>=7,p.streak>=30,level>=10,level>=25,level>=50,level>=75,level>=100].filter(Boolean).length;
const StatBox=({n,t})=><article><b>{n}</b><small>{t}</small></article>;
function Settings({go}){return <section><Top title="Settings" back={()=>go('me')}/><h3>Account</h3><button className="menu" onClick={async()=>{await supabase.auth.signOut();go('welcome')}}>Log out <b>›</b></button><h3>Local app data</h3><button className="menu" onClick={()=>{localStorage.removeItem(storageKey(localStorage.getItem(ACTIVE_USER_KEY)||''));location.reload()}}>Reset device data <b>›</b></button></section>}
createRoot(document.getElementById('root')).render(<App/>);
